(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["bg"] = {"ui":{"skip":"Към съдържанието","back":"← Обратно към AI-gile","lang.button":"Език: {name}","lang.dialog":"Избери език","lang.search":"Търси език","lang.none":"Няма съвпадащ език","lang.notYet":"{name} още не е преведен","theme.aria":"Превключване между светла и тъмна тема","theme.toLight":"Към светла тема","theme.toDark":"Към тъмна тема","words.underline":"Подчертай тези думи на страницата","words.underlineHelp":"Посочи или докосни дума с точки отдолу, за да видиш какво означава.","index.title":"AI-gile: твоят AI екип за разработка, на една дъска","index.description":"AI-gile е канбан дъска за екипи, които кодират с изкуствен интелект. Те работят, докато спиш; ти получаваш една кратка купчинка неща за решаване, тестване и приемане.","hero.logoAlt":"Икона на дъската на AI-gile","hero.h1.html":"Твоят AI екип за разработка, на една&nbsp;дъска.","hero.alpha":"🐣 Затворена пре-алфа","hero.alphaTitle":"Рано и недовършено: благодаря, че го пробваш!","hero.lede":"Те строят, докато спиш. Събуждаш се с една кратка купчинка: няколко въпроса, няколко неща за тестване, един-два лилави диаманта. Кликваш, приемаш и се връщаш към кафето си.","dl.windows":"Приложение за Windows","dl.browser":"Пусни го в браузъра","dl.soon":"Скоро","dl.notify":"🔔 Кажи ми, когато отвори","dl.notifySmall":"Алфа или бета","hero.secondary":"Аджайл, но екипът никога не се нуждае от кафе за стендъп. (Правят стендъпи така или иначе.)","pitch.h2":"AI-gile с колкото думи искаш","pitch.lede":"Избери дължина, от една дума до 144. Всяка дължина е отделно описание, написано за този размер. Плъзни плъзгача или използвай стрелките.","pitch.rangeLabel":"Дължина в думи","pitch.dice":"🎲 друга версия","pitch.words.one":"{n} дума","pitch.words.other":"{n} думи","pitch.letters.one":"{n} буква","pitch.letters.other":"{n} букви","pitch.chars.one":"{n} знак","pitch.chars.other":"{n} знака","count.line.html.one":"{n} карта на дъската в момента","count.line.html.other":"{n} карти на дъската в момента","features.aria":"Какво прави","f.pile.h":"Една купчинка за теб","f.pile.html":"<b>За теб</b> събира всичко, което чака теб, във всички проекти: въпроси, неща за тестване, задачи, които може да свърши само човек. Опашката ти казва кое е следващо и колко ще отнеме.","f.sleep.h":"Екипи, които работят, докато спиш","f.sleep.p":"Всеки проект има лидер и екип от AI агенти. Коментирай карта и екипът се събужда, върши работата и ти я връща със стъпки, които един уморен човек може да следва.","f.tester.h":"Първо проверява AI тестер","f.tester.p":"Преди нещо да стигне до теб, тестер следва стъпките в копие на приложението и показва какво е видял, със снимка на екрана. Прегледай миналите и приеми с един клик.","f.proof.h":"Доказателства, не обещания","f.proof.p":"Всяко предаване показва какво се е променило: файловете, разликата, снимките на екрана. Не е нужно да отваряш всяко приложение, за да видиш дали е готово.","f.chat.h":"Чати с лидерите си","f.chat.p":"Странична лента като в Discord: една икона за проект, лилави диаманти за онова, което чака теб. Пиши на лидер идея; той я превръща в карти и план, с бутон ✅ Давай.","f.tidy.h":"Подрежда се сам","f.tidy.p":"Сродните карти се сливат в една, объркани заглавия се оправят, а проверка на токените държи кода компактен. По-малко неща за превключване, по-малко за мислене.","f.private.h":"Твое, на твоя компютър","f.private.li1":"Дъската работи на твоята собствена машина и отговаря само на теб.","f.private.li2":"Личните съобщения между хората са шифровани от край до край.","f.private.li3":"Без акаунти, без тракери, без бисквитки.","f.lang.h":"На твоя език","f.lang.p":"Над 120 езика, от нидерландски, уелски и японски до пиратски, Йода и клингонски, с бързо превключване обратно към английски за програмистките думи.","tl.aria":"Времева линия от първия разговор до пътната карта","tl.h2":"От първия чат до следващото","tl.lede":"Истински дати и часове, в твоята часова зона. След днес това е планът, без обещани дати.","tl.today":"Днес","tl.planned":"планирано","tl.cards.one":"{n} карта","tl.cards.other":"{n} карти","join.h2":"Включи се","join.lede":"AI-gile се прави от един малък човек и много търпеливи агенти. Засега е частен, в затворена алфа с приятели. Искаш ли да го пробваш, когато се отвори?","join.btn":"Заяви интерес","join.small":"Ще ти пишем по имейл, нищо друго","footer.tag":"AI-gile. Без тракери, без бисквитки, без кафе за стендъп.","footer.licence":"Бизнес лиценз","footer.status":"Статус","footer.privacy":"Какво пазим","form.sending":"Изпраща се…","form.failed":"Не се получи: опитай пак по-късно.","form.offline":"Не успяхме да стигнем до AI-gile: опитай пак по-късно.","form.keep":"Използваме това само за да ти отговорим, после го изтриваме. Без тракери, без бисквитки.","form.keepLink":"Какво пазим","interest.title":"AI-gile: кажи ми, когато алфата се отвори","interest.description":"Остави имейла си, за да научиш кога се отваря затворената алфа или бета на AI-gile.","interest.h1":"🔔 Кажи ми, когато отвори","interest.lede":"AI-gile е в затворена пре-алфа. Остави имейла си и ще ти пишем веднъж, когато има място за теб.","interest.email":"Твоят имейл","interest.which":"Кой тест?","interest.alpha":"Затворена алфа: рано, грубо, много промени","interest.beta":"Бета: по-стабилна, по-късно","interest.both":"Която и да е, която дойде първа","interest.submit":"Запиши ме в списъка","interest.thanks":"Благодаря! В списъка си.","licence.title":"AI-gile: бизнес лиценз","licence.description":"Използваш ли AI-gile в бизнеса си? Кандидатствай за безплатен бизнес лиценз.","licence.h1":"📜 Бизнес лиценз","licence.lede":"Използваш ли AI-gile на работа? Кажи ни кой си и с какво се занимаваш. Ако върши някаква полза, лицензът е безплатен.","licence.company":"Компания","licence.website":"Уебсайт","licence.what":"С какво се занимаваш","licence.how":"Как помага на света","licence.email":"Имейл","licence.submit":"Кандидатствай","licence.thanks":"Благодаря! Ще ти отговорим по имейл.","status.title":"Статус на AI-gile","status.h1":"Статус на AI-gile","status.quiet":"Всичко е тихо","status.intro":"Работи ли AI-gile в момента? Тази страница проверява сайта, споделянето на дъски, разговорите и изтеглянето на всеки 5 минути.","status.up":"Работи (отговори за {ms} ms)","status.slow":"Не отговори на последната проверка, опитваме пак","status.down":"Не работи: не отговори на последните две проверки","status.svc.web":"Уебсайт","status.svc.web.offers":"Този сайт: какво е AI-gile и формата за интерес","status.svc.boards":"Споделяне на дъски","status.svc.boards.offers":"Публични дъски, съобщения между приятели и покани","status.svc.calls":"Разговори","status.svc.calls.offers":"Глас, видео и споделяне на екрана в AI-gile","status.svc.download":"Изтегляне","status.svc.download.offers":"Инсталаторът за Windows и линковете за покани","status.checking":"Проверява се…","status.offline":"В момента не може да се стигне до услугата за статус (опитва се пак)","status.updated":"обновено {ago}","status.justNow":"току-що","status.min":"преди {n} мин","status.hours":"преди {n} ч","status.days":"преди {n} д","privacy.title":"AI-gile: какво пазим","privacy.h1":"Какво пазим","privacy.lede":"Накратко: само това, което ни пращаш, и не за дълго.","privacy.only":"Само това, което ни пращаш: каквото напишеш във формата, например имейла си. Нищо друго за теб.","privacy.sealed":"Запечатва се, така че сървърът ни да не може да го прочете: в браузъра ти, преди да тръгне (при по-стар браузър – в момента, в който пристигне). Само нашата собствена дъска може да го отвори.","privacy.server":"Изтрива се от сървъра веднага щом стигне до дъската ни. Всичко, което още е там след 30 дни, се изтрива така или иначе.","privacy.board":"Пазим го на дъската си само докато ти отговорим, после го изтриваме и оттам.","privacy.none":"Без тракери, без бисквитки, без анализи.","privacy.local":"Езикът ти и изборът на светла или тъмна тема остават в собствения ти браузър. Никога не ни се изпращат.","privacy.ask":"Искаш да изчезне по-рано? Отговори на имейла ни и ни кажи.","live.h2":"Гледайте как се изгражда, на живо","live.caption":"Всяка карта е скрита: виждате формата на работата, не думите.","live.watching.one":"на живо: {n} гледа","live.watching.other":"на живо: {n} гледат","live.last.now":"Последната карта е преместена току-що","live.last.min.one":"Последната карта е преместена преди {n} мин","live.last.min.other":"Последната карта е преместена преди {n} мин","live.last.hour.one":"Последната карта е преместена преди {n} час","live.last.hour.other":"Последната карта е преместена преди {n} часа","live.last.day.one":"Последната карта е преместена преди {n} ден","live.last.day.other":"Последната карта е преместена преди {n} дни","live.offline":"Таблото на живо си почива за малко. Заповядайте пак скоро.","live.cols":"Backlog|За изпълнение|В процес|Екипът проверява|Чака твоя тест|За екипа|Готово"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Канбан.","Роботи.","Делегирано."]},{"n":2,"texts":["Роботи, канбан.","Агенти, подредени.","Идеи, построени."]},{"n":3,"texts":["Канбан за роботи.","Идеите стават функции.","Безплатен канбан за агенти."]},{"n":5,"texts":["Канбан дъска, водена от агенти.","Ти пишеш карти. Агентите строят.","Безплатно, локално, тествано, малко смахнато."]},{"n":8,"texts":["Безплатна канбан дъска, където работят AI агенти.","Напиши идея. Агентите я строят. Ти я приемаш.","Аджайл за един човек и много търпеливи роботи."]},{"n":13,"texts":["Канбан дъска на твоя компютър, където AI агентите поемат картите и ги изпълняват.","Напиши идея. Екип от агенти я строи. Тестер я проверява накрая.","Безплатно, без акаунти, без тракери: дъска, няколко робота и ти, който решаваш."]},{"n":21,"texts":["AI-gile е канбан дъска за работа с AI агенти за кодиране. Те поемат картите, а ти ги тестваш и приемаш.","Всеки проект получава лидер и екип от AI агенти. Коментирай всяка карта и екипът се залавя за работа.","Безплатна лична дъска със задачи, която работи на твоя компютър. Работниците са роботи. Този, който казва да, си ти."]},{"n":34,"texts":["Слагаш идеи на дъска. Екип от AI агенти ги превръща в работещи функции, тества ги и ти ги връща със стъпки за изпробване. Нищо не се брои за готово, докато ти не кажеш.","AI-gile е домашно направена канбан дъска, която Рич построи с голяма помощ от агентите, които сега управлява. Безплатна е, работи на твоя компютър и се споделя с приятели, не се продава.","Представи си обикновена канбан дъска с колони от Backlog до Готово, само че картите се поемат от AI агенти. Те докладват напредъка, питат, когато заседнат, и винаги чакат твоето одобрение."]},{"n":55,"texts":["AI-gile е канбан дъска, на която екипът е съставен от AI агенти. Всеки проект има лидер, който планира работата, и помощници, които я строят. Когато една функция е готова, AI тестер я изпробва и прави снимка на екрана, след което тя пристига в твоята купчинка. Приеми я или коментирай и те я правят наново.","Започна като начин един човек да следи много сесии за кодиране с AI едновременно и порасна до истинска дъска. Работи на твоята машина, не иска акаунт и няма тракери. Безплатна е за приятели и за всеки любопитен. Също така е недовършена, така че очаквай някоя и друга грапавина и от време на време изненада.","Ето честната версия. Все още трябва ти да измисляш идеите и ти да проверяваш резултатите. AI-gile върши всичко помежду им: подрежда картите, буди правилния агент, когато коментираш, показва точно какво се е променило и държи всичко в една кратка купчинка за теб, без излишен шум."]},{"n":89,"texts":["AI-gile е безплатна канбан дъска, която пускаш на собствения си компютър. Вместо хора всеки проект има екип от AI агенти: лидер, който превръща идеите ти в карти и план, и помощници, които поемат картите по приоритет. Когато нещо е построено, AI тестер следва стъпките за тестване и ти показва какво е видял. После то чака в една купчинка, наречена За теб. Приемаш го или коментираш и екипът опитва отново. Нищо никога не стига до Готово без теб.","Има и функции, които може да не очакваш. Нощна стража държи колоната За правене пълна, докато спиш, като избира карти, които не искат отговор от теб. Брояч на токени показва колко са използвали агентите днес и тази седмица, а Режим без токени им казва да спрат да харчат. Можеш да пишеш на приятели, а личните съобщения са шифровани от край до край. Дъската говори около 120 езика, включително нидерландски, фламандски, пиратски и клингонски. Нищо от това не струва и стотинка и никой не се опитва да ти го продава.","AI-gile е малък личен проект, не компания. Рич искаше да се грижи за няколко проекта с AI кодиране, без да отваря всяко приложение, за да ги проверява, затова двамата с агентите построиха дъска за това, а после я използваха, за да построят останалата част от себе си. В затворена пре-алфа е, което значи, че работи, повечето време, за шепа приятели. Няма страница с цени, няма бюлетин и няма план за растеж. Ако ти звучи полезно, можеш да поискаш да го пробваш, когато се отвори малко повече."]},{"n":144,"texts":["AI-gile е канбан дъска за един човек и много AI агенти. Работи на твоя собствен компютър и е напълно безплатна. Добавяш проекти и всеки проект получава лидер и малък екип. Чатиш с лидера, малко като в Discord, и описваш идея; лидерът я превръща в карти и план, после чака да натиснеш Давай. Екипът минава през картите по приоритет, като използва прост команден ред, направен за езикови модели. Преди нещо да се върне при теб, AI тестер следва стъпките в копие на приложението и прикрепя снимка на екрана. Готовата работа пристига в твоята купчинка с променените файлове и разликата. Приемаш я или оставяш коментар, и екипът се събужда и опитва пак. Само ти можеш да преместиш карта в Готово.","Един ден с AI-gile, приблизително. Вечерта оставяш няколко коментара: този бутон е на грешно място, този списък трябва да е подреден, можем ли да имаме тъмен режим. Лягаш си. Агентите четат коментарите, правят промените, тестват ги и ти ги връщат. Ако За правене се изпразни, нощната стража го допълва от backlog с карти, които не искат отговор от теб. Сутринта има една кратка купчинка: няколко въпроса и няколко неща за изпробване, всяко със стъпки, които може да следва един сънлив човек, и със снимка на екрана как работи. Кликваш, приемаш добрите и връщаш останалите. Брояч на токени показва какво е изразходвано, а Режим без токени е за оскъдните седмици. После закусваш, с което агентите още не могат да помогнат.","Първо, какво AI-gile не е. Не е стартъп, не се продава и никой не събира данните ти. Безплатна дъска е, която работи на твоя компютър, без акаунти, без тракери и без бисквитки. Какво е: едно подредено място да видиш всички проекти с AI кодиране наведнъж, с екип от агенти, който върши картите, и ти, който взимаш решенията. Слива сродните карти, оправя объркани заглавия и следи колко компактен остава кодът. Говори около 120 езика, от нидерландски и фламандски до пиратски и клингонски. Приятелите могат да си пишат, лично и шифровано. Направена е от Рич и много търпеливи агенти, най-вече като използват самата нея. В затворена пре-алфа е, така че на места е грапава. Ако ти звучи забавно, попитай любезно и може да влезеш рано."]}],"quips":{"1":"Една дума. Смело. Може би твърде смело.","3":"Три думи. Вече по-честно от повечето страници на продукти.","8":"Осем думи. Пак по-кратко от стендъп.","21":"Дължините са story points, между другото. Разбира се, че са.","55":"Петдесет и пет думи. Две карти се довършиха, докато четеше това.","144":"Това е дългата. Няма 233. Агентите си легнаха."}},"timeline":{"first-idea.name":"Първата идея","first-idea.line":"Най-първият разговор, преди да съществува и един ред код.","first-board.name":"Първата дъска","first-board.line":"Дъска, която следи собственото си изграждане: карти, колони, дърпане и пускане, проекти.","team-roles.name":"Екип и роли","team-roles.line":"Профили на агенти, шаблони за екипи, пространства и кой какво прави.","install.name":"Инсталиране и версии","install.line":"Zip, който приятел може да инсталира, самообновяване, канали и връщане назад.","usage-saver.name":"Спестяване на ресурси","usage-saver.line":"Мери колко струват пусканията, дръж кода компактен, пази лимита си.","friends.name":"Приятели и споделяне","friends.line":"Лични съобщения, шифровано реле, покани, роли и споделени проекти.","languages.name":"Езици","languages.line":"Всеки екранен текст в езиков файл, първо нидерландски и фламандски.","ai-tester.name":"AI тестер","ai-tester.line":"Тестер проверява всяко предаване първо и показва какво е видял.","website.name":"Уебсайтът","website.line":"aigile.lol, тийзърът и тази времева линия.","streaming.name":"Чат и стрийминг","streaming.line":"Discord, Twitch, OBS, режим за стриймъри, GIF-ове и емоджита.","no-ai.name":"Версия без AI","no-ai.line":"Дъска за хора, които кодират без AI, и публични дъски.","night-watch.name":"Нощна стража","night-watch.line":"Пазач и Scrum Master държат екипите на задачата, докато спиш.","p-more.name":"Всичко останало","p-more.line":"По-малки идеи, които още чакат реда си.","p-android.name":"Телефон и Android","p-android.line":"Стигай до дъската си от телефона, после и с родно Android приложение.","p-release.name":"Алфа и нататък","p-release.line":"Затворена алфа, живият сайт, после бета.","p-languages.name":"Още езици","p-languages.line":"Над сто езика и режим на потапяне за учещите.","p-engines.name":"Още AI двигатели","p-engines.line":"Избери Claude, Codex или Gemini за всеки агент.","p-pro.name":"Професионална практика","p-pro.line":"Етикети за риск, врати за сливане, карти за инциденти и предпазни огради.","p-self.name":"Грижа за теб","p-self.line":"Режим на умора, напомняния за грижа за себе си и 4:20.","p-servers.name":"Сървъри и мащаб","p-servers.line":"Глобални настройки на сървъра, роли и планиране за растеж.","p-livestream.name":"Допълнения за стрийминг","p-livestream.line":"Twitch чат, собствени емоджита и публичен жив изглед."},"words":{"button":"📖 Думи на разработчиците","h":"📖 Обяснение на думите на разработчиците","intro":"Думите, които разработчиците (и AI екипите) използват, на прост език.","search":"Търси дума…","none":"Няма дума, която да съвпада.","close":"Затвори","list":[{"id":"backlog","word":"Backlog","text":"Идеи и работа, които още не са планирани. Нищо там не се върши, докато не се премести в „За изпълнение“."},{"id":"sprint","word":"Спринт","text":"Кратък период работа (често седмица или две) с уговорен набор карти за привършване.","also":["спринт","спринта","спринтове","спринтовете","sprint","sprints"]},{"id":"standup","word":"Стендъп","text":"Бърза проверка: какво е направил всеки член на екипа, какво ще прави после и какво го спира.","also":["стендъп","стендъпа","стендъпи","стендъпите","standup","stand-up","stand-ups"]},{"id":"bug","word":"Бъг","text":"Нещо, което не работи както трябва.","also":["бъг","бъга","бъгове","бъговете","bug","bugs"]},{"id":"test","word":"Тест","text":"Изпробване на готова работа, за да се провери дали прави каквото е поискано, преди да я приемеш.","also":["тест","теста","тестове","тестовете","тестване","test","tests"],"noTip":1},{"id":"commit","word":"Къмит","text":"Запазена снимка на кода с кратка бележка какво е променено. Винаги можеш да се върнеш към някой.","also":["къмит","къмита","къмити","къмитите","commit","commits"]},{"id":"push","word":"Push","text":"Изпращане на запазените снимки (къмити) от този компютър към GitHub, за да са архивирани и споделени."},{"id":"branch","word":"Клон","text":"Отделна линия работа в кода, за да се правят промени, без да се пипа основната версия.","also":["клон","клона","клонове","клоновете","branch","branches"]},{"id":"merge","word":"Сливане","text":"Връщане на промените от един клон обратно в основната версия."},{"id":"repo","word":"Хранилище","text":"Папката на проекта с код и пълната му история от къмити, обикновено пазена и в GitHub.","also":["хранилище","хранилища","репо","repo","repository"]},{"id":"refactor","word":"Рефакториране","text":"Подреждане на кода, без да се променя какво прави: по-малки файлове, по-ясни имена, по-малко повторения."},{"id":"deploy","word":"Деплой","text":"Пускане на нова версия на живо, например на сървър, където хората я използват."},{"id":"kanban","word":"Канбан","text":"Табло с колони (За изпълнение, В процес, Готово), в което картите се движат отляво надясно, докато върви работата."},{"id":"wip","word":"WIP лимит","text":"Work in progress (работа в процес): най-много карти, които една колона трябва да държи, за да довършва екипът нещата, преди да започне още.","also":["WIP","wip лимит"]},{"id":"pr","word":"Pull request","text":"Искане промените на един клон да бъдат проверени и слети в основната версия.","also":["PR","pull request"]},{"id":"hook","word":"Hook","text":"Малка команда, която се изпълнява сама в определен момент, напр. когато започне AI сесия, за да чува екипът коментарите ти.","also":["hook","hook-ове","hook-а","hooks"]},{"id":"token","word":"Токен","text":"Единицата, в която се брои използването на AI: грубо няколко букви прочетен или написан текст. По-малко токени, повече останало от плана.","also":["токен","токена","токени","токените","token","tokens"]},{"id":"agent","word":"Агент","text":"AI, който работи самостоятелно по задача: чете кода, прави промени, пуска проверки и докладва.","also":["агент","агента","агенти","агентите","agent","agents"]}]}};
